#define _XOPEN_SOURCE 700

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "format.h"
#include "json.h"
#include "msg.h"
#include "session.h"
#include "transcript.h"
#include "util.h"

/*
 * The input field that says best what a tool call does, by rank; any other
 * string field is a last resort, the first one found.
 */
static const char *const arg_keys[] = {
	"command", "file_path", "notebook_path", "path", "pattern", "query",
	"url", "skill", "description", "subject", "prompt", NULL
};

#define ARG_OTHER 100

/* A content block of a line, as far as the view needs it. */
struct part {
	char *type;
	char *text;		/* text of a text block */
	char *name;		/* the tool of a tool_use block */
	char *arg;		/* its main argument */
	int rank;		/* of arg in arg_keys; ARG_OTHER + n otherwise */
	size_t lines;		/* lines of a tool_result */
	int error;		/* is_error of a tool_result */
};

/* What one line of a session file says for the view. */
struct line_scan {
	const char *line;
	char *type;
	char *timestamp;
	int is_meta;
	int is_compact;		/* the summary that starts a compacted session */
	char *content;		/* message.content when it is a string */
	struct part *parts;	/* message.content when it is an array */
	size_t part_count;
	int others;		/* string input fields seen, for their rank */
};

static char *token_text(const struct line_scan *f, const struct json_token *tok)
{
	return json_decode_string(f->line + tok->start + 1,
	    tok->end - tok->start - 2);
}

static void set_text(char **slot, const struct line_scan *f,
    const struct json_token *tok)
{
	free(*slot);
	*slot = tok->kind == JSON_STRING ? token_text(f, tok) : NULL;
}

static int is_true(const struct line_scan *f, const struct json_token *tok)
{
	return tok->kind == JSON_LITERAL && tok->end - tok->start == 4 &&
	    strncmp(f->line + tok->start, "true", 4) == 0;
}

/*
 * Lines of a JSON string, from its raw bytes: escaped newlines plus one,
 * a newline at the very end not starting another line. Results can be
 * megabytes, so they are counted without decoding.
 */
static size_t raw_lines(const char *raw, size_t len)
{
	size_t i, n = 1;
	int last = 0;

	if (len <= 2)
		return 0;
	for (i = 1; i + 1 < len; i++) {
		last = 0;
		if (raw[i] != '\\')
			continue;
		if (raw[i + 1] == 'n') {
			n++;
			last = 1;
		}
		i++;
	}
	return last ? n - 1 : n;
}

static int arg_rank(const char *key, int *others)
{
	int i;

	for (i = 0; arg_keys[i] != NULL; i++)
		if (strcmp(arg_keys[i], key) == 0)
			return i;
	return ARG_OTHER + (*others)++;
}

static struct part *part_at(struct line_scan *f, size_t index)
{
	size_t i;

	while (f->part_count <= index) {
		i = f->part_count++;
		f->parts = xrealloc(f->parts, f->part_count * sizeof *f->parts);
		memset(&f->parts[i], 0, sizeof f->parts[i]);
		f->parts[i].rank = -1;
	}
	return &f->parts[index];
}

static void scan_token(const struct json_token *tok, void *ctx)
{
	struct line_scan *f = ctx;
	const struct json_seg *p = tok->path;
	struct part *b;
	int rank;

	if (tok->is_key || tok->depth == 0 || p[0].key == NULL)
		return;
	if (tok->depth == 1) {
		if (strcmp(p[0].key, "type") == 0)
			set_text(&f->type, f, tok);
		else if (strcmp(p[0].key, "timestamp") == 0)
			set_text(&f->timestamp, f, tok);
		else if (strcmp(p[0].key, "isMeta") == 0)
			f->is_meta = is_true(f, tok);
		else if (strcmp(p[0].key, "isCompactSummary") == 0)
			f->is_compact = is_true(f, tok);
		return;
	}
	if (strcmp(p[0].key, "message") != 0 || p[1].key == NULL ||
	    strcmp(p[1].key, "content") != 0)
		return;
	if (tok->depth == 2) {
		set_text(&f->content, f, tok);
		return;
	}
	if (tok->depth < 4 || p[2].key != NULL || p[3].key == NULL)
		return;
	b = part_at(f, p[2].index);
	if (tok->depth == 4) {
		if (strcmp(p[3].key, "type") == 0)
			set_text(&b->type, f, tok);
		else if (strcmp(p[3].key, "text") == 0)
			set_text(&b->text, f, tok);
		else if (strcmp(p[3].key, "name") == 0)
			set_text(&b->name, f, tok);
		else if (strcmp(p[3].key, "is_error") == 0)
			b->error = is_true(f, tok);
		else if (strcmp(p[3].key, "content") == 0 &&
		    tok->kind == JSON_STRING)
			b->lines += raw_lines(f->line + tok->start,
			    tok->end - tok->start);
		return;
	}
	if (tok->depth == 5 && strcmp(p[3].key, "input") == 0 &&
	    p[4].key != NULL && tok->kind == JSON_STRING) {
		rank = arg_rank(p[4].key, &f->others);
		if (b->rank < 0 || rank < b->rank) {
			set_text(&b->arg, f, tok);
			b->rank = rank;
		}
		return;
	}
	if (tok->depth == 6 && strcmp(p[3].key, "content") == 0 &&
	    p[4].key == NULL && p[5].key != NULL &&
	    strcmp(p[5].key, "text") == 0 && tok->kind == JSON_STRING)
		b->lines += raw_lines(f->line + tok->start,
		    tok->end - tok->start);
}

static void scan_free(struct line_scan *f)
{
	size_t i;

	for (i = 0; i < f->part_count; i++) {
		free(f->parts[i].type);
		free(f->parts[i].text);
		free(f->parts[i].name);
		free(f->parts[i].arg);
	}
	free(f->parts);
	free(f->type);
	free(f->timestamp);
	free(f->content);
}

/* The first n bytes of s, which has at least that many. */
static char *copy_n(const char *s, size_t n)
{
	char *out;

	out = xmalloc(n + 1);
	memcpy(out, s, n);
	out[n] = '\0';
	return out;
}

static int is_space(int c)
{
	return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

/* s without blank space at either end, or NULL when nothing is left. */
static char *trimmed(const char *s)
{
	size_t n;

	if (s == NULL)
		return NULL;
	while (is_space((unsigned char)*s))
		s++;
	n = strlen(s);
	while (n > 0 && is_space((unsigned char)s[n - 1]))
		n--;
	if (n == 0)
		return NULL;
	return copy_n(s, n);
}

static struct transcript_entry *add(struct transcript *tr,
    enum transcript_kind kind, time_t when)
{
	struct transcript_entry *e;

	if (tr->count == tr->cap) {
		tr->cap = tr->cap ? tr->cap * 2 : 64;
		tr->entries = xrealloc(tr->entries,
		    tr->cap * sizeof *tr->entries);
	}
	e = &tr->entries[tr->count++];
	memset(e, 0, sizeof *e);
	e->kind = kind;
	e->when = when;
	return e;
}

static void add_user_text(struct transcript *tr, const char *text,
    time_t when)
{
	char *shown, *t;

	if (text == NULL)
		return;
	shown = session_text(text);
	t = trimmed(shown);
	free(shown);
	if (t != NULL)
		add(tr, TRANSCRIPT_USER, when)->text = t;
}

static int part_is(const struct part *b, const char *type)
{
	return b->type != NULL && strcmp(b->type, type) == 0;
}

/*
 * The entries of one line. A user line is a prompt (its text as -s
 * reads it: no meta lines, nothing Claude Code put there itself), images
 * and documents, or tool results; an assistant line holds blocks of a
 * reply, as a rule one: text, a tool call, or thinking, which the view
 * leaves out.
 */
static void add_line(struct transcript *tr, const struct line_scan *f)
{
	struct transcript_entry *e;
	const struct part *b;
	time_t when = 0;
	char *t;
	size_t i;
	int user;

	if (f->type == NULL)
		return;
	user = strcmp(f->type, "user") == 0;
	if (!user && strcmp(f->type, "assistant") != 0)
		return;
	if (f->timestamp != NULL && parse_iso(f->timestamp, &when) != 0)
		when = 0;
	if (user && f->is_compact) {
		add(tr, TRANSCRIPT_COMPACT, when);
		return;
	}
	if (user && f->is_meta)
		return;
	if (user && f->content != NULL) {
		add_user_text(tr, f->content, when);
		return;
	}
	for (i = 0; i < f->part_count; i++) {
		b = &f->parts[i];
		if (user && part_is(b, "text")) {
			add_user_text(tr, b->text, when);
		} else if (user && part_is(b, "image")) {
			add(tr, TRANSCRIPT_IMAGE, when);
		} else if (user && part_is(b, "document")) {
			add(tr, TRANSCRIPT_DOCUMENT, when);
		} else if (user && part_is(b, "tool_result")) {
			e = add(tr, TRANSCRIPT_RESULT, when);
			e->lines = b->lines;
			e->error = b->error;
		} else if (!user && part_is(b, "text")) {
			if ((t = trimmed(b->text)) != NULL)
				add(tr, TRANSCRIPT_CLAUDE, when)->text = t;
		} else if (!user && part_is(b, "tool_use")) {
			e = add(tr, TRANSCRIPT_TOOL, when);
			e->text = xstrdup(b->name != NULL ? b->name : "?");
			e->arg = trimmed(b->arg);
		}
	}
}

/*
 * Reads a session file in one pass, a line at a time. Only what the view
 * shows is kept: prompts, replies, one line per tool call and the size
 * of each result, so a file of gigabytes, nearly all of it tool output,
 * needs little more memory than its longest line. Lines
 * that are not valid JSON (a last line still being written) are skipped.
 * -1 with errno when the file cannot be read.
 */
int transcript_read(const char *file, struct transcript *tr)
{
	struct line_scan f;
	char *line = NULL;
	size_t cap = 0;
	ssize_t len;
	FILE *fp;

	memset(tr, 0, sizeof *tr);
	fp = fopen(file, "r");
	if (fp == NULL)
		return -1;
	while ((len = getline(&line, &cap, fp)) > 0) {
		memset(&f, 0, sizeof f);
		f.line = line;
		if (json_scan(line, (size_t)len, scan_token, &f) == 0)
			add_line(tr, &f);
		scan_free(&f);
	}
	free(line);
	fclose(fp);
	return 0;
}

void transcript_free(struct transcript *tr)
{
	size_t i;

	for (i = 0; i < tr->count; i++) {
		free(tr->entries[i].text);
		free(tr->entries[i].arg);
	}
	free(tr->entries);
	memset(tr, 0, sizeof *tr);
}

struct out {
	struct view_line *lines;
	size_t count, cap;
};

/* Adds a line; the text is taken over. */
static void put(struct out *o, enum view_style style, char *text)
{
	if (o->count == o->cap) {
		o->cap = o->cap ? o->cap * 2 : 128;
		o->lines = xrealloc(o->lines, o->cap * sizeof *o->lines);
	}
	o->lines[o->count].style = style;
	o->lines[o->count].text = text;
	o->count++;
}

/* The first n bytes of s cleaned for the terminal. */
static char *clean_n(const char *s, size_t n)
{
	char *raw, *clean;

	raw = copy_n(s, n);
	clean = text_clean(raw);
	free(raw);
	return clean;
}

/* Two spaces and the first n bytes of s, cleaned for the terminal. */
static char *indented(const char *s, size_t n)
{
	char *clean, *out;

	clean = clean_n(s, n);
	out = xmalloc(strlen(clean) + 3);
	sprintf(out, "  %s", clean);
	free(clean);
	return out;
}

/*
 * A prompt or a reply, line by line, two columns in; wrapped to width
 * (0: not wrapped) on word boundaries, the indent kept.
 */
static void put_text(struct out *o, const char *text, size_t width)
{
	const char *p, *nl;
	char *buf = NULL, *line, **wrapped;
	size_t len = 0, n, i;

	for (p = text;; p = nl + 1) {
		nl = strchr(p, '\n');
		line = indented(p, nl != NULL ? (size_t)(nl - p) : strlen(p));
		if (width == 0) {
			put(o, VIEW_TEXT, line);
		} else {
			n = strlen(line);
			buf = xrealloc(buf, len + n + 2);
			memcpy(buf + len, line, n);
			len += n;
			buf[len++] = '\n';
			free(line);
		}
		if (nl == NULL)
			break;
	}
	if (width == 0)
		return;
	wrapped = text_wrap(buf, len - 1, width, &n);
	for (i = 0; i < n; i++)
		put(o, VIEW_TEXT, wrapped[i]);
	free(wrapped);
	free(buf);
}

/* One line, cut to width (0: as it is). */
static void put_short(struct out *o, enum view_style style, char *text,
    size_t width)
{
	char *cut;

	if (width == 0) {
		put(o, style, text);
		return;
	}
	cut = text_fit(text, width);
	free(text);
	put(o, style, cut);
}

static char *head(const char *key, time_t when)
{
	char *t, *out;

	t = when != 0 ? format_time(when) : xstrdup(msg("value.none"));
	out = msg_text(key, t);
	free(t);
	return out;
}

/* The tool, and the first line of its main argument. */
static char *tool_line(const struct transcript_entry *e)
{
	char *name, *arg, *text, *out;

	name = text_clean(e->text);
	if (e->arg == NULL) {
		text = msg_text("view.tool.bare", name);
	} else {
		arg = clean_n(e->arg, strcspn(e->arg, "\n"));
		text = msg_text("view.tool", name, arg);
		free(arg);
	}
	free(name);
	out = indented(text, strlen(text));
	free(text);
	return out;
}

static char *result_line(const struct transcript_entry *e)
{
	char *num, *text, *out;

	num = format_count(e->lines);
	text = msg_text(e->error ? "view.result.error" : "view.result", num);
	out = indented(text, strlen(text));
	free(text);
	free(num);
	return out;
}

/*
 * The lines of the view for a screen width columns wide (0: a pipe, no
 * wrapping and no cutting). Each side of the conversation has a header
 * with the time it starts; a reply goes on through its tool calls, each
 * one line, and their results, each with its number of lines.
 */
struct view_line *transcript_lines(const struct transcript *tr, size_t width,
    size_t *count)
{
	const struct transcript_entry *e;
	struct out o = { NULL, 0, 0 };
	const char *key;
	size_t i;
	int side = 0, now, fresh;

	for (i = 0; i < tr->count; i++) {
		e = &tr->entries[i];
		if (e->kind == TRANSCRIPT_COMPACT) {
			if (o.count > 0)
				put(&o, VIEW_BLANK, xstrdup(""));
			put_short(&o, VIEW_NOTE, xstrdup(msg("view.compact")),
			    width);
			side = 0;
			continue;
		}
		now = e->kind == TRANSCRIPT_USER ||
		    e->kind == TRANSCRIPT_IMAGE ||
		    e->kind == TRANSCRIPT_DOCUMENT ? 1 : 2;
		fresh = now != side;
		if (fresh) {
			if (o.count > 0)
				put(&o, VIEW_BLANK, xstrdup(""));
			put_short(&o, now == 1 ? VIEW_HEAD_USER :
			    VIEW_HEAD_CLAUDE, head(now == 1 ? "view.you" :
			    "view.claude", e->when), width);
			side = now;
		}
		switch (e->kind) {
		case TRANSCRIPT_USER:
		case TRANSCRIPT_CLAUDE:
			if (!fresh)
				put(&o, VIEW_BLANK, xstrdup(""));
			put_text(&o, e->text, width);
			break;
		case TRANSCRIPT_IMAGE:
		case TRANSCRIPT_DOCUMENT:
			key = e->kind == TRANSCRIPT_IMAGE ? "view.image" :
			    "view.document";
			put_short(&o, VIEW_TEXT, indented(msg(key),
			    strlen(msg(key))), width);
			break;
		case TRANSCRIPT_TOOL:
			put_short(&o, VIEW_TOOL, tool_line(e), width);
			break;
		case TRANSCRIPT_RESULT:
			put_short(&o, VIEW_TOOL, result_line(e), width);
			break;
		case TRANSCRIPT_COMPACT:
			break;
		}
	}
	if (o.count == 0)
		put_short(&o, VIEW_NOTE, xstrdup(msg("view.empty")), width);
	*count = o.count;
	return o.lines;
}

void transcript_lines_free(struct view_line *lines, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++)
		free(lines[i].text);
	free(lines);
}
